const km = 1200;
const glassKmPerMs = 200000 / 1000;   // 200 ms-worth per... → km per ms
const hollowKmPerMs = 295000 / 1000;
const glassOneWay = km / glassKmPerMs;
const hollowOneWay = km / hollowKmPerMs;
const rttSaving = 2 * (glassOneWay - hollowOneWay);
console.log('glass one-way (ms):', glassOneWay.toFixed(3));
console.log('hollow one-way (ms):', hollowOneWay.toFixed(3));
console.log('RTT saving (ms):', rttSaving.toFixed(3));
